            // Mark invoice as paid since payment already succeeded
            if (finalizedInvoice.id) {
              await stripe.invoices.pay(finalizedInvoice.id, {
                paid_out_of_band: true
              });
            }

            invoiceUrl = finalizedInvoice.invoice_pdf;
