import express, { type Express } from "express";
import fs from "fs";
import path from "path";
import { createServer as createViteServer, createLogger } from "vite";
import { type Server } from "http";
import viteConfig from "../vite.config";
import { nanoid } from "nanoid";

const viteLogger = createLogger();

export function log(message: string, source = "express") {
  const formattedTime = new Date().toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
    second: "2-digit",
    hour12: true,
  });

  console.log(`${formattedTime} [${source}] ${message}`);
}

export async function setupVite(app: Express, server: Server) {
  const serverOptions = {
    middlewareMode: true,
    hmr: { server },
    allowedHosts: true as const,
  };

  const vite = await createViteServer({
    ...viteConfig,
    configFile: false,
    customLogger: {
      ...viteLogger,
      error: (msg, options) => {
        viteLogger.error(msg, options);
        process.exit(1);
      },
    },
    server: serverOptions,
    appType: "custom",
  });

  app.use(vite.middlewares);
  app.use("*", async (req, res, next) => {
    const url = req.originalUrl;

    try {
      const clientTemplate = path.resolve(
        import.meta.dirname,
        "..",
        "client",
        "index.html",
      );

      // always reload the index.html file from disk incase it changes
      let template = await fs.promises.readFile(clientTemplate, "utf-8");
      template = template.replace(
        `src="/src/main.tsx"`,
        `src="/src/main.tsx?v=${nanoid()}"`,
      );
      const page = await vite.transformIndexHtml(url, template);
      res.status(200).set({ "Content-Type": "text/html" }).end(page);
    } catch (e) {
      vite.ssrFixStacktrace(e as Error);
      next(e);
    }
  });
}

export function serveStatic(app: Express) {
  const distPath = path.resolve(import.meta.dirname, "public");

  if (!fs.existsSync(distPath)) {
    throw new Error(
      `Could not find the build directory: ${distPath}, make sure to build the client first`,
    );
  }

  app.use(express.static(distPath));

  // fall through to index.html if the file doesn't exist
  app.use("*", (_req, res) => {
    res.sendFile(path.resolve(distPath, "index.html"));
  });
}

client/src/components/org-messaging.tsx.content:
import { useState, useEffect, useRef } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { useAuth } from "@/hooks/useAuth";
import { useToast } from "@/hooks/use-toast";
import { format, formatDistanceToNow, isToday, isYesterday } from "date-fns";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import {
  Hash,
  Send,
  CheckCircle2,
  Clock,
  MessageSquare,
  Mail,
  ArrowLeft,
} from "lucide-react";

interface Message {
  id: number;
  orgId: number;
  senderId: string;
  recipientId?: string;
  messageType: 'community' | 'dm';
  content: string;
  attachments?: any;
  isRead: boolean;
  createdAt: string;
  sender?: {
    id: string;
    firstName: string;
    lastName: string;
    email: string;
    userType: string;
  };
}

interface Conversation {
  participantId: string;
  participantName: string;
  participantType: 'user' | 'org_member';
  lastMessage: string;
  lastMessageAt: Date;
  unreadCount: number;
}

interface OrgMember {
  id: string;
  name: string;
  email: string;
  role: string;
  type: 'user' | 'org_member';
}

interface OrgMessagingProps {
  userType: 'org_owner' | 'coach' | 'org_client';
  orgId?: number;
  className?: string;
  embedded?: boolean;
}

export function OrgMessaging({ userType, orgId, className, embedded = false }: OrgMessagingProps) {
  const { user } = useAuth();
  const { toast } = useToast();
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const [messageInput, setMessageInput] = useState("");
  const [activeTab, setActiveTab] = useState<'community' | 'dm'>('community');
  const [selectedConversation, setSelectedConversation] = useState<string | null>(null);
  const [newDmRecipient, setNewDmRecipient] = useState<string>("");

  // Get organization ID from prop or user context
  const organizationId = orgId || (user as any)?.currentOrgId || (user as any)?.organizationId;
  const userId = user?.id;
  const userName = `${user?.firstName} ${user?.lastName}`;

  // Everyone can now send messages!
  const canSendMessages = true;

  // Fetch community messages
  const { data: messages = [], isLoading: loadingMessages } = useQuery({
    queryKey: ['/api/organizations', organizationId, 'messages', 'community'],
    queryFn: async () => {
      const response = await apiRequest(
        `/api/organizations/${organizationId}/messages?messageType=community&limit=100`,
        'GET'
      );
      return response.messages || [];
    },
    enabled: !!organizationId && activeTab === 'community',
    refetchInterval: 5000
  });

  // Fetch DM conversations
  const { data: conversations = [], isLoading: loadingConversations } = useQuery<Conversation[]>({
    queryKey: ['/api/organizations', organizationId, 'messages', 'dm'],
    queryFn: async () => {
      const response = await apiRequest(
        `/api/organizations/${organizationId}/messages/dm`,
        'GET'
      );
      return response.conversations || [];
    },
    enabled: !!organizationId && activeTab === 'dm',
    refetchInterval: 5000
  });

  // Fetch DM thread with selected participant
  const { data: dmMessages = [], isLoading: loadingDmThread } = useQuery({
    queryKey: ['/api/organizations', organizationId, 'messages', 'dm', selectedConversation],
    queryFn: async () => {
      const response = await apiRequest(
        `/api/organizations/${organizationId}/messages/dm/${selectedConversation}`,
        'GET'
      );
      return response.messages || [];
    },
    enabled: !!organizationId && !!selectedConversation,
    refetchInterval: 3000
  });

  // Fetch organization members for DM recipient selection
  const { data: orgMembers = [] } = useQuery<OrgMember[]>({
    queryKey: ['/api/organizations', organizationId, 'members'],
    queryFn: async () => {
      const response = await apiRequest(
        `/api/organizations/${organizationId}/members`,
        'GET'
      );
      return (response.members || []).filter((m: OrgMember) => m.id !== userId);
    },
    enabled: !!organizationId && activeTab === 'dm'
  });

  // Send community message mutation
  const sendCommunityMessageMutation = useMutation({
    mutationFn: async (data: { content: string }) => {
      return apiRequest(`/api/organizations/${organizationId}/messages`, 'POST', data);
    },
    onSuccess: () => {
      setMessageInput("");
      queryClient.invalidateQueries({ 
        queryKey: ['/api/organizations', organizationId, 'messages', 'community'] 
      });
      scrollToBottom();
    },
    onError: (error: any) => {
      toast({
        title: "Failed to send message",
        description: error.message,
        variant: "destructive"
      });
    }
  });

  // Send DM mutation
  const sendDmMutation = useMutation({
    mutationFn: async (data: { recipientId: string; recipientType: string; content: string }) => {
      return apiRequest(`/api/organizations/${organizationId}/messages/dm`, 'POST', data);
    },
    onSuccess: () => {
      setMessageInput("");
      queryClient.invalidateQueries({ 
        queryKey: ['/api/organizations', organizationId, 'messages', 'dm'] 
      });
      queryClient.invalidateQueries({ 
        queryKey: ['/api/organizations', organizationId, 'messages', 'dm', selectedConversation] 
      });
      scrollToBottom();
    },
    onError: (error: any) => {
      toast({
        title: "Failed to send message",
        description: error.message,
        variant: "destructive"
      });
    }
  });

  // Mark messages as read mutation
  const markAsReadMutation = useMutation({
    mutationFn: async (messageIds: number[]) => {
      return apiRequest(`/api/organizations/${organizationId}/messages/read`, 'PATCH', { messageIds });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ 
        queryKey: ['/api/organizations', organizationId, 'messages', 'dm'] 
      });
    }
  });

  // Auto-scroll to bottom when new messages arrive
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, dmMessages]);

  // Mark DM messages as read when conversation is opened
  useEffect(() => {
    if (selectedConversation && dmMessages.length > 0) {
      // Find unread messages sent TO the current user
      const unreadMessages = dmMessages.filter(
        (msg: Message) => !msg.isRead && msg.recipientId === userId
      );

      if (unreadMessages.length > 0) {
        const messageIds = unreadMessages.map((msg: Message) => msg.id);
        markAsReadMutation.mutate(messageIds);
      }
    }
  }, [selectedConversation, dmMessages, userId]);

  // Format message timestamp
  const formatMessageTime = (timestamp: string | Date) => {
    const date = new Date(timestamp);
    const now = new Date();
    const diffInMinutes = Math.floor((now.getTime() - date.getTime()) / (1000 * 60));

    if (diffInMinutes < 1) return "Just now";
    if (diffInMinutes < 60) return formatDistanceToNow(date, { addSuffix: true });
    if (isToday(date)) return format(date, "h:mm a");
    if (isYesterday(date)) return `Yesterday at ${format(date, "h:mm a")}`;
    return format(date, "MMM d at h:mm a");
  };

  // Get user initials for avatar
  const getUserInitials = (name: string) => {
    return name
      .split(' ')
      .map(word => word[0])
      .join('')
      .toUpperCase()
      .slice(0, 2);
  };

  // Handle sending community message
  const handleSendCommunityMessage = () => {
    if (!messageInput.trim()) return;
    sendCommunityMessageMutation.mutate({ content: messageInput });
  };

  // Handle sending DM
  const handleSendDm = () => {
    if (!messageInput.trim()) return;

    const recipient = selectedConversation || newDmRecipient;
    if (!recipient) {
      toast({
        title: "Select a recipient",
        description: "Please select someone to send a message to",
        variant: "destructive"
      });
      return;
    }

    const recipientMember = orgMembers.find(m => m.id === recipient);
    if (!recipientMember) return;

    sendDmMutation.mutate({
      recipientId: recipient,
      recipientType: recipientMember.type,
      content: messageInput
    });
  };

  // Render community tab
  const renderCommunityTab = () => (
    <div className="flex flex-col h-full">
      {/* Community Header */}
      <div className="border-b px-6 py-4 flex items-center justify-between bg-white dark:bg-gray-900 flex-shrink-0">
        <div className="flex items-center gap-3">
          <Hash className="h-6 w-6 text-primary" />
          <div>
            <h3 className="font-semibold text-lg">Community</h3>
            <p className="text-xs text-gray-500">
              Share updates and announcements with your organization
            </p>
          </div>
        </div>
      </div>

      {/* Messages Area */}
      <ScrollArea className="flex-1 min-h-0 p-6">
        {loadingMessages ? (
          <div className="space-y-4">
            {[...Array(5)].map((_, i) => (
              <div key={i} className="flex items-start gap-3">
                <Skeleton className="h-10 w-10 rounded-full" />
                <div className="space-y-2 flex-1">
                  <Skeleton className="h-4 w-32" />
                  <Skeleton className="h-16 w-full" />
                </div>
              </div>
            ))}
          </div>
        ) : messages.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center text-gray-500 py-8">
            <MessageSquare className="h-16 w-16 mb-4 text-gray-400" />
            <p className="text-xl font-medium">No messages yet</p>
            <p className="text-sm mt-2">
              Start the conversation by posting a message below
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {messages.map((message: Message) => {
              const isOwnMessage = message.senderId === userId;
              const senderName = isOwnMessage 
                ? userName 
                : message.sender ? `${message.sender.firstName} ${message.sender.lastName}` : 'Unknown User';

              return (
                <div
                  key={message.id}
                  className={cn(
                    "flex items-start gap-3",
                    isOwnMessage && "flex-row-reverse"
                  )}
                >
                  <Avatar className="h-10 w-10 flex-shrink-0">
                    <AvatarFallback className="text-xs">
                      {getUserInitials(senderName)}
                    </AvatarFallback>
                  </Avatar>
                  <div className={cn(
                    "flex-1 space-y-1",
                    isOwnMessage && "items-end"
                  )}>
                    <div className={cn(
                      "flex items-center gap-2",
                      isOwnMessage && "justify-end"
                    )}>
                      <span className="font-medium text-sm">{senderName}</span>
                      <span className="text-xs text-gray-500">
                        {formatMessageTime(message.createdAt)}
                      </span>
                      {isOwnMessage && (
                        message.isRead 
                          ? <CheckCircle2 className="h-3 w-3 text-blue-500" />
                          : <Clock className="h-3 w-3 text-gray-400" />
                      )}
                    </div>
                    <div className={cn(
                      "rounded-lg px-4 py-2 max-w-2xl",
                      isOwnMessage 
                        ? "bg-primary text-primary-foreground ml-auto" 
                        : "bg-gray-100 dark:bg-gray-800"
                    )}>
                      <p className="whitespace-pre-wrap break-words">{message.content}</p>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
        <div ref={messagesEndRef} />
      </ScrollArea>

      {/* Message Input */}
      <div className="border-t p-4 bg-white dark:bg-gray-900 flex-shrink-0">
        <div className="flex gap-2">
          <Input
            type="text"
            placeholder="Post a message to the community..."
            value={messageInput}
            onChange={(e) => setMessageInput(e.target.value)}
            onKeyPress={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                handleSendCommunityMessage();
              }
            }}
            className="flex-1"
            data-testid="input-community-message"
          />
          <Button 
            onClick={handleSendCommunityMessage}
            disabled={!messageInput.trim() || sendCommunityMessageMutation.isPending}
            data-testid="button-send-message"
          >
            <Send className="h-4 w-4" />
          </Button>
        </div>
      </div>
    </div>
  );

  // Render DM conversation list
  const renderDmConversationList = () => (
    <div className="flex flex-col h-full">
      {/* DM Header */}
      <div className="border-b px-6 py-4 bg-white dark:bg-gray-900 flex-shrink-0">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Mail className="h-6 w-6 text-primary" />
            <div>
              <h3 className="font-semibold text-lg">Direct Messages</h3>
              <p className="text-xs text-gray-500">Private conversations</p>
            </div>
          </div>
        </div>
      </div>

      {/* New DM Section */}
      <div className="p-4 border-b bg-gray-50 dark:bg-gray-800/50 flex-shrink-0">
        <div className="flex gap-2">
          <Select value={newDmRecipient} onValueChange={(value) => {
            setNewDmRecipient(value);
            setSelectedConversation(value);
          }}>
            <SelectTrigger className="flex-1" data-testid="select-dm-recipient">
              <SelectValue placeholder="Start a new conversation..." />
            </SelectTrigger>
            <SelectContent>
              {orgMembers.map((member) => (
                <SelectItem key={member.id} value={member.id}>
                  {member.name} ({member.role})
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Conversations List */}
      <ScrollArea className="flex-1 min-h-0">
        {loadingConversations ? (
          <div className="p-4 space-y-2">
            {[...Array(3)].map((_, i) => (
              <Skeleton key={i} className="h-16 w-full" />
            ))}
          </div>
        ) : conversations.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center text-gray-500 p-8">
            <Mail className="h-16 w-16 mb-4 text-gray-400" />
            <p className="text-lg font-medium">No conversations yet</p>
            <p className="text-sm mt-2">Select someone above to start chatting</p>
          </div>
        ) : (
          <div className="p-2">
            {conversations.map((conv) => (
              <button
                key={conv.participantId}
                onClick={() => setSelectedConversation(conv.participantId)}
                className={cn(
                  "w-full p-4 rounded-lg text-left hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors",
                  selectedConversation === conv.participantId && "bg-gray-100 dark:bg-gray-800"
                )}
                data-testid={`conversation-${conv.participantId}`}
              >
                <div className="flex items-start justify-between">
                  <div className="flex items-start gap-3 flex-1">
                    <Avatar className="h-10 w-10">
                      <AvatarFallback className="text-xs">
                        {getUserInitials(conv.participantName)}
                      </AvatarFallback>
                    </Avatar>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-medium text-sm truncate">{conv.participantName}</span>
                        {conv.unreadCount > 0 && (
                          <Badge variant="default" className="ml-2">
                            {conv.unreadCount}
                          </Badge>
                        )}
                      </div>
                      <p className="text-xs text-gray-500 truncate">{conv.lastMessage}</p>
                      <p className="text-xs text-gray-400 mt-1">
                        {formatMessageTime(conv.lastMessageAt)}
                      </p>
                    </div>
                  </div>
                </div>
              </button>
            ))}
          </div>
        )}
      </ScrollArea>
    </div>
  );

  // Render DM thread
  const renderDmThread = () => {
    const participant = conversations.find(c => c.participantId === selectedConversation) ||
                        orgMembers.find(m => m.id === selectedConversation);
    const participantName = participant && 'participantName' in participant 
      ? participant.participantName 
      : participant && 'name' in participant 
      ? participant.name 
      : 'Unknown';

    return (
      <div className="flex flex-col h-full">
        {/* DM Thread Header */}
        <div className="border-b px-6 py-4 flex items-center gap-3 bg-white dark:bg-gray-900 flex-shrink-0">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setSelectedConversation(null)}
            data-testid="button-back-to-conversations"
          >
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <Avatar className="h-8 w-8">
            <AvatarFallback className="text-xs">
              {getUserInitials(participantName)}
            </AvatarFallback>
          </Avatar>
          <div>
            <h3 className="font-semibold">{participantName}</h3>
          </div>
        </div>

        {/* Messages Area */}
        <ScrollArea className="flex-1 min-h-0 p-6">
          {loadingDmThread ? (
            <div className="space-y-4">
              {[...Array(3)].map((_, i) => (
                <Skeleton key={i} className="h-20 w-full" />
              ))}
            </div>
          ) : dmMessages.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full text-center text-gray-500 py-8">
              <MessageSquare className="h-16 w-16 mb-4 text-gray-400" />
              <p className="text-lg font-medium">No messages yet</p>
              <p className="text-sm mt-2">Send a message to start the conversation</p>
            </div>
          ) : (
            <div className="space-y-4">
              {dmMessages.map((message: Message) => {
                const isOwnMessage = message.senderId === userId;
                const senderName = isOwnMessage 
                  ? userName 
                  : message.sender ? `${message.sender.firstName} ${message.sender.lastName}` : participantName;

                return (
                  <div
                    key={message.id}
                    className={cn(
                      "flex items-start gap-3",
                      isOwnMessage && "flex-row-reverse"
                    )}
                  >
                    <Avatar className="h-8 w-8 flex-shrink-0">
                      <AvatarFallback className="text-xs">
                        {getUserInitials(senderName)}
                      </AvatarFallback>
                    </Avatar>
                    <div className={cn(
                      "flex-1 space-y-1 max-w-xs",
                      isOwnMessage && "items-end"
                    )}>
                      <div className={cn(
                        "rounded-lg px-4 py-2",
                        isOwnMessage 
                          ? "bg-primary text-primary-foreground ml-auto" 
                          : "bg-gray-100 dark:bg-gray-800"
                      )}>
                        <p className="whitespace-pre-wrap break-words text-sm">{message.content}</p>
                      </div>
                      <div className={cn(
                        "flex items-center gap-1 text-xs text-gray-500 px-1",
                        isOwnMessage && "justify-end"
                      )}>
                        <span>{formatMessageTime(message.createdAt)}</span>
                        {isOwnMessage && (
                          message.isRead 
                            ? <CheckCircle2 className="h-3 w-3 text-blue-500" />
                            : <Clock className="h-3 w-3 text-gray-400" />
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
          <div ref={messagesEndRef} />
        </ScrollArea>

        {/* Message Input */}
        <div className="border-t p-4 bg-white dark:bg-gray-900 flex-shrink-0">
          <div className="flex gap-2">
            <Input
              type="text"
              placeholder="Send a message..."
              value={messageInput}
              onChange={(e) => setMessageInput(e.target.value)}
              onKeyPress={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleSendDm();
                }
              }}
              className="flex-1"
              data-testid="input-dm-message"
            />
            <Button 
              onClick={handleSendDm}
              disabled={!messageInput.trim() || sendDmMutation.isPending}
              data-testid="button-send-dm"
            >
              <Send className="h-4 w-4" />
            </Button>
          </div>
        </div>
      </div>
    );
  };

  // Main content
  return (
    <div className={cn("flex flex-col h-full", className)}>
      <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as 'community' | 'dm')} className="flex-1 flex flex-col">
        <TabsList className="grid w-full grid-cols-2">
          <TabsTrigger value="community" data-testid="tab-community">
            <Hash className="h-4 w-4 mr-2" />
            Community
          </TabsTrigger>
          <TabsTrigger value="dm" data-testid="tab-dm">
            <Mail className="h-4 w-4 mr-2" />
            Direct Messages
            {conversations.reduce((sum, c) => sum + c.unreadCount, 0) > 0 && (
              <Badge variant="destructive" className="ml-2 h-5 min-w-5 px-1.5">
                {conversations.reduce((sum, c) => sum + c.unreadCount, 0)}
              </Badge>
            )}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="community" className="flex-1 mt-0">
          {renderCommunityTab()}
        </TabsContent>

        <TabsContent value="dm" className="flex-1 mt-0">
          {selectedConversation ? renderDmThread() : renderDmConversationList()}
        </TabsContent>
      </Tabs>
    </div>
  );
}

client/src/components/ui/progress-bar.ts.content:
import { motion } from "framer-motion";
import { progressBar } from "@/lib/animations";
import { cn } from "@/lib/utils";

interface ProgressBarProps {
  value: number; // 0-100
  className?: string;
  height?: "sm" | "md" | "lg";
  showValue?: boolean;
  color?: "primary" | "success" | "warning" | "error";
}

export function ProgressBar({ 
  value, 
  className, 
  height = "md", 
  showValue = false,
  color = "primary" 
}: ProgressBarProps) {
  const heightClasses = {
    sm: "h-1",
    md: "h-2",
    lg: "h-3"
  };

  const colorClasses = {
    primary: "bg-primary",
    success: "bg-green-500",
    warning: "bg-yellow-500", 
    error: "bg-red-500"
  };

  return (
    <div className={cn("w-full", className)}>
      {showValue && (
        <div className="flex justify-between items-center mb-2">
          <span className="text-sm text-muted-foreground">Progress</span>
          <span className="text-sm font-medium">{value}%</span>
        </div>
      )}
      <div className={cn("w-full bg-muted rounded-full overflow-hidden", heightClasses[height])}>
        <motion.div
          variants={progressBar}
          initial="initial"
          animate="animate"
          style={{ scaleX: value / 100 }}
          className={cn("h-full origin-left rounded-full", colorClasses[color])}
        />
      </div>
    </div>
  );
}

client/src/components/recipe-card.tsx.content:
import { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { 
  Clock, 
  Users, 
  Star, 
  Heart, 
  Plus,
  Flame,
  ChefHat,
  Utensils
} from "lucide-react";

interface Recipe {
  id: number;
  name: string;
  description: string;
  cuisine: string;
  mealType: string;
  cookingTime: number;
  servings: number;
  calories: number;
  protein: string;
  carbs: string;
  fats: string;
  ingredients: any;
  instructions: string[];
  imageUrl?: string;
  tags: string[];
  difficulty: string;
  rating: string;
  createdBy?: string;
  createdAt?: string;
}

interface RecipeCardProps {
  recipe: Recipe;
  onAddToMealPlan?: (recipe: Recipe) => void;
}

export default function RecipeCard({ recipe, onAddToMealPlan }: RecipeCardProps) {
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [isLiked, setIsLiked] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);

  const addToMealPlanMutation = useMutation({
    mutationFn: async (recipeId: number) => {
      // This would typically add to an active meal plan
      return await apiRequest("POST", "/api/meal-plans/current/items", {
        recipeId,
        day: 1, // or current day
        mealType: recipe.mealType,
        servings: 1
      });
    },
    onSuccess: () => {
      toast({
        title: "Added to meal plan!",
        description: `${recipe.name} has been added to your meal plan.`,
      });
    },
    onError: (error) => {
      toast({
        title: "Error adding to meal plan",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const handleAddToMealPlan = () => {
    if (onAddToMealPlan) {
      onAddToMealPlan(recipe);
    } else if (recipe.id) {
      addToMealPlanMutation.mutate(recipe.id);
    } else {
      toast({
        title: "Error adding to meal plan",
        description: "Recipe ID is missing. Please try again.",
        variant: "destructive",
      });
    }
  };

  const handleToggleLike = () => {
    setIsLiked(!isLiked);
    // In a real app, this would make an API call
    toast({
      title: isLiked ? "Removed from favorites" : "Added to favorites",
      description: isLiked ? `${recipe.name} removed from favorites` : `${recipe.name} added to favorites`,
    });
  };

  const getDifficultyColor = (difficulty: string) => {
    switch (difficulty) {
      case 'easy':
        return 'bg-success text-white';
      case 'medium':
        return 'bg-warning text-white';
      case 'hard':
        return 'bg-error text-white';
      default:
        return 'bg-gray-500 text-white';
    }
  };

  const getMealTypeIcon = (mealType: string) => {
    switch (mealType) {
      case 'breakfast':
        return '🌅';
      case 'lunch':
        return '🌞';
      case 'dinner':
        return '🌙';
      case 'snack':
        return '🍎';
      default:
        return '🍽️';
    }
  };

  return (
    <Card className="overflow-hidden hover:shadow-lg transition-shadow duration-200">
      <div className="relative">
        {recipe.imageUrl ? (
          <img 
            src={recipe.imageUrl} 
            alt={recipe.name} 
            className="w-full h-48 object-cover"
          />
        ) : (
          <div className="w-full h-48 bg-gradient-to-br from-gray-100 to-gray-200 flex items-center justify-center">
            <ChefHat className="h-12 w-12 text-gray-400" />
          </div>
        )}

        {/* Floating badges */}
        <div className="absolute top-2 left-2">
          <Badge variant="secondary" className="bg-white/90 text-accent">
            {recipe.cuisine}
          </Badge>
        </div>

        <div className="absolute top-2 right-2 flex items-center space-x-1">
          <div className="bg-white/90 rounded-full p-1">
            <Star className="h-4 w-4 text-yellow-400 fill-current" />
          </div>
          <span className="text-xs bg-white/90 px-2 py-1 rounded">
            {parseFloat(recipe.rating).toFixed(1)}
          </span>
        </div>

        {/* Meal type indicator */}
        <div className="absolute bottom-2 left-2">
          <div className="bg-white/90 rounded-full px-2 py-1 flex items-center space-x-1">
            <span className="text-sm">{getMealTypeIcon(recipe.mealType)}</span>
            <span className="text-xs font-medium capitalize">{recipe.mealType}</span>
          </div>
        </div>
      </div>

      <CardContent className="p-4">
        <div className="flex items-start justify-between mb-2">
          <h3 className="font-semibold text-gray-800 text-lg leading-tight">
            {recipe.name}
          </h3>
          <Button
            variant="ghost"
            size="sm"
            onClick={handleToggleLike}
            className="p-1 h-8 w-8"
          >
            <Heart className={`h-4 w-4 ${isLiked ? 'fill-red-500 text-red-500' : 'text-gray-400'}`} />
          </Button>
        </div>

        <p className="text-sm text-gray-600 mb-3 line-clamp-2">
          {recipe.description}
        </p>

        <div className="flex items-center justify-between text-sm text-gray-600 mb-3">
          <div className="flex items-center space-x-3">
            <div className="flex items-center space-x-1">
              <Clock className="h-4 w-4" />
              <span>{recipe.cookingTime} min</span>
            </div>
            <div className="flex items-center space-x-1">
              <Flame className="h-4 w-4" />
              <span>{recipe.calories} cal</span>
            </div>
            <div className="flex items-center space-x-1">
              <Users className="h-4 w-4" />
              <span>{recipe.servings}</span>
            </div>
          </div>
          <Badge className={getDifficultyColor(recipe.difficulty)}>
            {recipe.difficulty}
          </Badge>
        </div>

        {/* Nutrition info */}
        <div className="grid grid-cols-3 gap-2 text-xs text-gray-600 mb-3">
          <div className="text-center">
            <div className="font-semibold text-accent">{recipe.protein}g</div>
            <div>Protein</div>
          </div>
          <div className="text-center">
            <div className="font-semibold text-primary">{recipe.carbs}g</div>
            <div>Carbs</div>
          </div>
          <div className="text-center">
            <div className="font-semibold text-warning">{recipe.fats}g</div>
            <div>Fats</div>
          </div>
        </div>

        {/* Tags */}
        {recipe.tags && recipe.tags.length > 0 && (
          <div className="flex flex-wrap gap-1 mb-3">
            {recipe.tags.slice(0, 3).map((tag, index) => (
              <Badge key={index} variant="outline" className="text-xs">
                {tag}
              </Badge>
            ))}
            {recipe.tags.length > 3 && (
              <Badge variant="outline" className="text-xs">
                +{recipe.tags.length - 3} more
              </Badge>
            )}
          </div>
        )}

        {/* Action buttons */}
        <div className="flex space-x-2">
          <Button
            onClick={handleAddToMealPlan}
            disabled={addToMealPlanMutation.isPending}
            className="flex-1 bg-primary text-white hover:bg-primary/90"
            size="sm"
          >
            <Plus className="h-4 w-4 mr-1" />
            Add to Plan
          </Button>
          <Button
            variant="outline"
            onClick={() => setIsExpanded(!isExpanded)}
            size="sm"
          >
            <Utensils className="h-4 w-4" />
          </Button>
        </div>

        {/* Expanded content */}
        {isExpanded && (
          <div className="mt-4 pt-4 border-t">
            <div className="space-y-3">
              <div>
                <h4 className="font-semibold text-sm mb-2">Ingredients:</h4>
                <ul className="text-sm text-gray-600 space-y-1">
                  {recipe.ingredients?.items && recipe.ingredients.items.slice(0, 5).map((ingredient: string, index: number) => (
                    <li key={index} className="flex items-center">
                      <span className="w-2 h-2 bg-primary rounded-full mr-2"></span>
                      {ingredient}
                    </li>
                  ))}
                  {recipe.ingredients?.items && recipe.ingredients.items.length > 5 && (
                    <li className="text-xs text-gray-500">
                      ...and {recipe.ingredients.items.length - 5} more ingredients
                    </li>
                  )}
                </ul>
              </div>

              <div>
                <h4 className="font-semibold text-sm mb-2">Instructions:</h4>
                <ol className="text-sm text-gray-600 space-y-1">
                  {recipe.instructions.slice(0, 3).map((step, index) => (
                    <li key={index} className="flex">
                      <span className="font-medium text-primary mr-2">{index + 1}.</span>
                      <span>{step}</span>
                    </li>
                  ))}
                  {recipe.instructions.length > 3 && (
                    <li className="text-xs text-gray-500 ml-6">
                      ...and {recipe.instructions.length - 3} more steps
                    </li>
                  )}
                </ol>
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

client/src/pages/profile-setup.tsx.content:
import { useState } from "react";
import { useLocation } from "wouter";
import { useAuth } from "@/hooks/useAuth";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { X, Plus, Upload, User, Building, Phone, Calendar, MapPin, Award, Users, Globe, Clock } from "lucide-react";
import { Navigation } from "@/components/navigation";
import { DisclaimerSection, CompactDisclaimer } from "@/components/disclaimer";

export default function ProfileSetup() {
  const { user } = useAuth();
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const isCoach = (user as any)?.userType === "coach";

  // Individual profile form data
  const [individualFormData, setIndividualFormData] = useState({
    age: "",
    height: "",
    weight: "",
    activityLevel: "",
    goal: "",
    targetCalories: "",
    targetProtein: "",
    targetCarbs: "",
    targetFats: "",
    dietaryPreferences: [] as string[],
    allergens: [] as string[],
    culturalPreferences: [] as string[],
  });

  // Coach profile form data  
  const [coachFormData, setCoachFormData] = useState({
    profileType: "",
    phoneNumber: "",
    yearsOfExperience: "",
    specializations: [] as string[],
    address: "",
    profileBio: "",
    certifications: [] as string[],
    availability: {
      monday: { start: "", end: "", available: false },
      tuesday: { start: "", end: "", available: false },
      wednesday: { start: "", end: "", available: false },
      thursday: { start: "", end: "", available: false },
      friday: { start: "", end: "", available: false },
      saturday: { start: "", end: "", available: false },
      sunday: { start: "", end: "", available: false },
    },
    languagesSpoken: [] as string[],
    trainingStyle: "",
    hourlyRate: "",
    servicesOffered: [] as string[],
    qualifications: [] as string[],
    businessLicense: "",
    organizationName: "",
    teamSize: "",
  });

  const [newPreference, setNewPreference] = useState("");
  const [newAllergen, setNewAllergen] = useState("");
  const [newCulturalPref, setNewCulturalPref] = useState("");
  const [newSpecialization, setNewSpecialization] = useState("");
  const [newCertification, setNewCertification] = useState("");
  const [newLanguage, setNewLanguage] = useState("");
  const [newService, setNewService] = useState("");
  const [newQualification, setNewQualification] = useState("");

  const commonDietaryPreferences = [
    "Vegetarian", "Vegan", "Keto", "Low-Carb", "High-Protein", "Mediterranean", "Paleo", "Gluten-Free"
  ];

  const commonAllergens = [
    "Nuts", "Dairy", "Eggs", "Soy", "Gluten", "Shellfish", "Fish", "Sesame"
  ];

  const commonCulturalPreferences = [
    "Italian", "Mexican", "Indian", "Chinese", "Japanese", "Mediterranean", "Thai", "Middle Eastern", "French", "Korean"
  ];

  // Coach-specific options
  const commonSpecializations = [
    "Weight Loss", "Strength Training", "Yoga", "Cardio Fitness", "Nutrition Counseling", 
    "Bodybuilding", "CrossFit", "Pilates", "Sports Performance", "Rehabilitation", 
    "Senior Fitness", "Youth Training", "Functional Training", "HIIT"
  ];

  const commonLanguages = [
    "English", "Spanish", "French", "German", "Italian", "Portuguese", "Mandarin", 
    "Hindi", "Arabic", "Japanese", "Korean", "Russian"
  ];

  const commonServices = [
    "Personal Training", "Group Classes", "Nutrition Planning", "Meal Prep Guidance",
    "Online Coaching", "Fitness Assessments", "Exercise Program Design", "Lifestyle Coaching",
    "Weight Management", "Sport-Specific Training", "Injury Prevention", "Wellness Consulting"
  ];

  const trainingStyles = [
    "one-on-one", "group", "online", "hybrid", "bootcamp", "personalized"
  ];

  const profileMutation = useMutation({
    mutationFn: async (data: any) => {
      const endpoint = isCoach ? "/api/coach-profile" : "/api/profile";
      return await apiRequest(endpoint, "POST", data);
    },
    onSuccess: () => {
      const queryKey = isCoach ? ["/api/coach-profile"] : ["/api/profile"];
      queryClient.invalidateQueries({ queryKey });
      toast({
        title: "Profile created successfully!",
        description: isCoach 
          ? "Your professional coach profile has been set up." 
          : "Your personalized nutrition profile has been set up.",
      });
      setLocation(isCoach ? "/coach-home" : "/");
    },
    onError: (error) => {
      toast({
        title: "Error creating profile",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (isCoach) {
      // Validate coach form
      if (!coachFormData.profileType || !coachFormData.phoneNumber || !coachFormData.yearsOfExperience) {
        toast({
          title: "Missing required fields",
          description: "Please fill in all required coach profile information.",
          variant: "destructive",
        });
        return;
      }

      const coachData = {
        ...coachFormData,
        yearsOfExperience: parseInt(coachFormData.yearsOfExperience) || 0,
        hourlyRate: coachFormData.hourlyRate ? parseFloat(coachFormData.hourlyRate) : null,
        teamSize: coachFormData.teamSize ? parseInt(coachFormData.teamSize) : null,
      };

      profileMutation.mutate(coachData);
    } else {
      // Individual form validation and submission
      if (!individualFormData.age || !individualFormData.height || !individualFormData.weight) {
        toast({
          title: "Missing required fields",
          description: "Please fill in your basic health information.",
          variant: "destructive",
        });
        return;
      }

      const individualData = {
        ...individualFormData,
        age: parseInt(individualFormData.age) || 0,
        height: parseFloat(individualFormData.height) || 0,
        weight: parseFloat(individualFormData.weight) || 0,
        targetCalories: parseInt(individualFormData.targetCalories) || 0,
        targetProtein: parseInt(individualFormData.targetProtein) || 0,
        targetCarbs: parseInt(individualFormData.targetCarbs) || 0,
        targetFats: parseInt(individualFormData.targetFats) || 0,
      };

      profileMutation.mutate(individualData);
    }
  };

  const addToList = (list: string[], newItem: string, setter: (items: string[]) => void) => {
    if (newItem.trim() && !list.includes(newItem.trim())) {
      setter([...list, newItem.trim()]);
    }
  };

  const removeFromList = (list: string[], item: string, setter: (items: string[]) => void) => {
    setter(list.filter(i => i !== item));
  };

  const updateCoachFormData = (field: string, value: any) => {
    setCoachFormData(prev => ({ ...prev, [field]: value }));
  };

  const updateIndividualFormData = (field: string, value: any) => {
    setIndividualFormData(prev => ({ ...prev, [field]: value }));
  };

  const updateAvailability = (day: keyof typeof coachFormData.availability, field: string, value: any) => {
    setCoachFormData(prev => ({
      ...prev,
      availability: {
        ...prev.availability,
        [day]: { ...prev.availability[day], [field]: value }
      }
    }));
  };

  if (!user) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <Navigation />

      <div className="container mx-auto px-4 py-8">
        <div className="max-w-4xl mx-auto">
          <div className="text-center mb-8">
            <h1 className="text-3xl font-bold text-gray-900 mb-4">
              {isCoach ? "Complete Your Coach Profile" : "Set Up Your Profile"}
            </h1>
            <p className="text-gray-600">
              {isCoach 
                ? "Help clients find you by providing your professional details and expertise."
                : "Help us personalize your nutrition and fitness journey."
              }
            </p>
          </div>

          {/* Disclaimer Section */}
          <DisclaimerSection />

          <form onSubmit={handleSubmit} className="space-y-8">
            {isCoach ? (
              // Coach Profile Form
              <>
