                      </div>
                    </div>

                    <div className="grid md:grid-cols-2 gap-4">
                      <div>
                        <Label htmlFor="activityLevel">Activity Level</Label>
                        <Select value={individualFormData.activityLevel} onValueChange={(value) => updateIndividualFormData("activityLevel", value)}>
