  // Get habit streaks from real data
  const habitStreak = (habits as any[] || []).map((habit: any) => {
    const todayLog = (habitLogs as any[] || []).find((log: any) => log.habitId === habit.id);
    return {
      habit: habit.name,
      streak: habit.streak || 0,
      completed: !!todayLog?.completed,
      id: habit.id
