client/src/components/workout-generator..content:
import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Dumbbell, Loader2, Target, Clock, Zap } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

export default function WorkoutGenerator() {
  const { toast } = useToast();
  const [isGenerating, setIsGenerating] = useState(false);
  const [fitnessGoal, setFitnessGoal] = useState("");
  const [experienceLevel, setExperienceLevel] = useState("");
  const [daysPerWeek, setDaysPerWeek] = useState("");
  const [duration, setDuration] = useState("");
  const [equipment, setEquipment] = useState<string[]>([]);
  const [limitations, setLimitations] = useState("");
  const [generatedWorkout, setGeneratedWorkout] = useState<any>(null);

  const equipmentOptions = [
    "Dumbbells",
    "Barbell",
    "Resistance Bands",
    "Pull-up Bar",
    "Kettlebell",
    "No Equipment"
  ];

  const toggleEquipment = (item: string) => {
    setEquipment(prev =>
      prev.includes(item) ? prev.filter(e => e !== item) : [...prev, item]
    );
  };

  const handleGenerate = async () => {
    if (!fitnessGoal || !experienceLevel || !daysPerWeek || !duration) {
      toast({
        title: "Missing information",
        description: "Please fill in all required fields.",
        variant: "destructive",
      });
      return;
    }

    setIsGenerating(true);

    // Simulate API call - Replace with actual FastAPI endpoint
    setTimeout(() => {
      setGeneratedWorkout({
        title: `${daysPerWeek}-Day ${fitnessGoal} Plan`,
        description: `Customized for ${experienceLevel} level, ${duration} sessions`,
        days: [
          {
            name: "Upper Body",
            exercises: [
              { name: "Push-ups", sets: 3, reps: "12-15" },
              { name: "Dumbbell Rows", sets: 3, reps: "10-12" },
              { name: "Shoulder Press", sets: 3, reps: "10-12" }
            ]
          }
        ]
      });
      setIsGenerating(false);
      toast({
        title: "Workout generated!",
        description: "Your personalized workout plan is ready.",
      });
    }, 2000);
  };

  return (
    <div className="max-w-5xl mx-auto">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center text-2xl">
            <Dumbbell className="mr-3 h-6 w-6 text-emerald-600" />
            AI Workout Generator
          </CardTitle>
          <p className="text-gray-600 dark:text-gray-300">
            Get a personalized workout plan tailored to your goals and experience
          </p>
        </CardHeader>
        <CardContent>
          <div className="grid md:grid-cols-2 gap-6">
            {/* Left Column - Input Form */}
            <div className="space-y-4">
              <div>
                <Label htmlFor="goal">Fitness Goal *</Label>
                <Select value={fitnessGoal} onValueChange={setFitnessGoal}>
                  <SelectTrigger id="goal" data-testid="select-fitness-goal">
                    <SelectValue placeholder="Select your goal" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="Muscle Building">Muscle Building</SelectItem>
                    <SelectItem value="Weight Loss">Weight Loss</SelectItem>
                    <SelectItem value="Strength">Strength</SelectItem>
                    <SelectItem value="Endurance">Endurance</SelectItem>
                    <SelectItem value="General Fitness">General Fitness</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label htmlFor="level">Experience Level *</Label>
                <Select value={experienceLevel} onValueChange={setExperienceLevel}>
                  <SelectTrigger id="level" data-testid="select-experience">
                    <SelectValue placeholder="Select level" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="Beginner">Beginner</SelectItem>
                    <SelectItem value="Intermediate">Intermediate</SelectItem>
                    <SelectItem value="Advanced">Advanced</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label htmlFor="days">Days Per Week *</Label>
                <Select value={daysPerWeek} onValueChange={setDaysPerWeek}>
                  <SelectTrigger id="days" data-testid="select-days-per-week">
                    <SelectValue placeholder="Select days" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="3">3 Days</SelectItem>
                    <SelectItem value="4">4 Days</SelectItem>
                    <SelectItem value="5">5 Days</SelectItem>
                    <SelectItem value="6">6 Days</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label htmlFor="duration">Session Duration *</Label>
                <Select value={duration} onValueChange={setDuration}>
                  <SelectTrigger id="duration" data-testid="select-duration">
                    <SelectValue placeholder="Select duration" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="30 minutes">30 minutes</SelectItem>
                    <SelectItem value="45 minutes">45 minutes</SelectItem>
                    <SelectItem value="60 minutes">60 minutes</SelectItem>
                    <SelectItem value="90 minutes">90 minutes</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label className="mb-2 block">Available Equipment</Label>
                <div className="flex flex-wrap gap-2">
                  {equipmentOptions.map((item) => (
                    <Badge
                      key={item}
                      variant={equipment.includes(item) ? "default" : "outline"}
                      className="cursor-pointer hover:scale-105 transition-transform"
                      onClick={() => toggleEquipment(item)}
                      data-testid={`badge-equipment-${item.toLowerCase().replace(/\s+/g, '-')}`}
                    >
                      {item}
                    </Badge>
                  ))}
                </div>
              </div>

              <div>
                <Label htmlFor="limitations">Injuries or Limitations (optional)</Label>
                <Textarea
                  id="limitations"
                  value={limitations}
                  onChange={(e) => setLimitations(e.target.value)}
                  placeholder="E.g., lower back pain, knee injury..."
                  rows={3}
                  data-testid="textarea-limitations"
                />
              </div>

              <Button
                onClick={handleGenerate}
                disabled={isGenerating}
                className="w-full bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-600 hover:to-teal-600 text-white"
                data-testid="button-generate-workout"
              >
                {isGenerating ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Generating...
                  </>
                ) : (
                  <>
                    <Zap className="mr-2 h-4 w-4" />
                    Generate Workout Plan
                  </>
                )}
              </Button>
            </div>

            {/* Right Column - Generated Workout */}
            <div>
              {generatedWorkout ? (
                <Card className="bg-gradient-to-br from-emerald-50 to-teal-50 dark:from-emerald-950 dark:to-teal-950 border-emerald-200">
                  <CardHeader>
                    <CardTitle className="flex items-center text-emerald-700 dark:text-emerald-300">
                      <Target className="mr-2 h-5 w-5" />
                      {generatedWorkout.title}
                    </CardTitle>
                    <p className="text-sm text-emerald-600 dark:text-emerald-400">
                      {generatedWorkout.description}
                    </p>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    {generatedWorkout.days.map((day: any, idx: number) => (
                      <div key={idx} className="bg-white dark:bg-gray-800 rounded-lg p-4 shadow">
                        <h4 className="font-semibold text-gray-800 dark:text-gray-200 mb-3 flex items-center">
                          <Clock className="mr-2 h-4 w-4 text-emerald-600" />
                          {day.name}
                        </h4>
                        <div className="space-y-2">
                          {day.exercises.map((exercise: any, eidx: number) => (
                            <div key={eidx} className="flex justify-between items-center text-sm border-b border-gray-100 dark:border-gray-700 pb-2">
                              <span className="font-medium text-gray-700 dark:text-gray-300">
                                {exercise.name}
                              </span>
                              <span className="text-gray-600 dark:text-gray-400">
                                {exercise.sets} × {exercise.reps}
                              </span>
                            </div>
                          ))}
                        </div>
                      </div>
                    ))}
                    <p className="text-xs text-emerald-700 dark:text-emerald-300 mt-4">
                      💡 This is a preview. Full workout integration coming soon!
                    </p>
                  </CardContent>
                </Card>
              ) : (
                <div className="h-full flex items-center justify-center bg-gray-50 dark:bg-gray-800 rounded-lg border-2 border-dashed border-gray-300 dark:border-gray-700 p-8">
                  <div className="text-center">
                    <Dumbbell className="mx-auto h-12 w-12 text-gray-400 mb-3" />
                    <p className="text-gray-500 dark:text-gray-400">
                      Fill in your details and generate your personalized workout plan
                    </p>
                  </div>
                </div>
              )}
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

client/src/components/meal-generator.tsx.content:
import { useState } from "react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Search, Clock, Users, ChefHat, Loader2, Youtube, Sparkles, UtensilsCrossed } from "lucide-react";
import { generateRecipe, type RecipeData } from "@/lib/recipesApi";
import { useToast } from "@/hooks/use-toast";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";

export default function MealGenerator() {
  const [dishName, setDishName] = useState("");
  const [servings, setServings] = useState<number>(4);
  const [cuisine, setCuisine] = useState("");
  const [dietaryPrefs, setDietaryPrefs] = useState<string[]>([]);
  const [excludeIngredients, setExcludeIngredients] = useState("");
  const [isGenerating, setIsGenerating] = useState(false);
  const [recipe, setRecipe] = useState<RecipeData | null>(null);
  const { toast } = useToast();

  const dietaryOptions = [
    "vegetarian",
    "vegan",
    "gluten-free",
    "dairy-free",
    "keto",
    "paleo",
    "low-carb",
    "high-protein",
  ];

  const cuisineOptions = [
    "Italian",
    "Indian",
    "Chinese",
    "Mexican",
    "Thai",
    "Japanese",
    "French",
    "Mediterranean",
    "American",
    "Korean",
    "Middle Eastern",
    "Vietnamese",
  ];

  const toggleDietaryPref = (pref: string) => {
    setDietaryPrefs((prev) =>
      prev.includes(pref) ? prev.filter((p) => p !== pref) : [...prev, pref]
    );
  };

  const handleSearch = async () => {
    if (!dishName.trim()) {
      toast({
        title: "Dish name required",
        description: "Please enter a dish name to search for a recipe.",
        variant: "destructive",
      });
      return;
    }

    setIsGenerating(true);
    setRecipe(null);

    try {
      const excludedList = excludeIngredients
        .split(",")
        .map((i) => i.trim())
        .filter((i) => i.length > 0);

      const response = await generateRecipe(
        dishName,
        servings,
        cuisine || undefined,
        dietaryPrefs.length > 0 ? dietaryPrefs : undefined,
        excludedList.length > 0 ? excludedList : undefined
      );

      setRecipe(response.recipe);
      toast({
        title: "Recipe generated!",
        description: `Found a great recipe for ${response.recipe.title}`,
      });
    } catch (error) {
      console.error("Recipe generation error:", error);
      toast({
        title: "Generation failed",
        description: error instanceof Error ? error.message : "Could not generate recipe. Please try again.",
        variant: "destructive",
      });
    } finally {
      setIsGenerating(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSearch();
    }
  };

  return (
    <div className="max-w-6xl mx-auto">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center text-2xl">
            <ChefHat className="mr-3 h-6 w-6 text-orange-600" />
            AI Meal Generator
          </CardTitle>
          <p className="text-gray-600 dark:text-gray-300">
            Get personalized recipes with step-by-step instructions
          </p>
        </CardHeader>
        <CardContent>
          {/* Search Form */}
          <div className="space-y-4 mb-8 bg-gradient-to-br from-orange-50 to-amber-50 dark:from-orange-950 dark:to-amber-950 p-6 rounded-lg">
            <div className="grid md:grid-cols-2 gap-4">
              <div>
                <Label htmlFor="dish">What would you like to cook? *</Label>
                <Input
                  id="dish"
                  type="text"
                  placeholder="e.g., Chicken Tikka Masala"
                  value={dishName}
                  onChange={(e) => setDishName(e.target.value)}
                  onKeyPress={handleKeyPress}
                  className="mt-1"
                  data-testid="input-dish-name"
                />
              </div>

              <div>
                <Label htmlFor="servings">Servings</Label>
                <Input
                  id="servings"
                  type="number"
                  min="1"
                  max="20"
                  value={servings}
                  onChange={(e) => setServings(parseInt(e.target.value) || 4)}
                  className="mt-1"
                  data-testid="input-servings"
                />
              </div>
            </div>

            <div>
              <Label htmlFor="cuisine">Cuisine Style (optional)</Label>
              <Select value={cuisine} onValueChange={setCuisine}>
                <SelectTrigger id="cuisine" className="mt-1" data-testid="select-cuisine">
                  <SelectValue placeholder="Any cuisine" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">Any cuisine</SelectItem>
                  {cuisineOptions.map((c) => (
                    <SelectItem key={c} value={c}>
                      {c}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label className="mb-2 block">Dietary Preferences</Label>
              <div className="flex flex-wrap gap-2">
                {dietaryOptions.map((pref) => (
                  <Badge
                    key={pref}
                    variant={dietaryPrefs.includes(pref) ? "default" : "outline"}
                    className="cursor-pointer hover:scale-105 transition-transform bg-orange-600 hover:bg-orange-700"
                    onClick={() => toggleDietaryPref(pref)}
                    data-testid={`badge-dietary-${pref}`}
                  >
                    {pref}
                  </Badge>
                ))}
              </div>
            </div>

            <div>
              <Label htmlFor="exclude">Exclude Ingredients (comma-separated)</Label>
              <Textarea
                id="exclude"
                placeholder="e.g., peanuts, shellfish"
                value={excludeIngredients}
                onChange={(e) => setExcludeIngredients(e.target.value)}
                rows={2}
                className="mt-1"
                data-testid="textarea-exclude-ingredients"
              />
            </div>

            <Button
              onClick={handleSearch}
              disabled={isGenerating || !dishName.trim()}
              className="w-full bg-gradient-to-r from-orange-500 to-amber-500 hover:from-orange-600 hover:to-amber-600 text-white text-lg py-6"
              data-testid="button-generate-recipe"
            >
              {isGenerating ? (
                <>
                  <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                  Generating recipe...
                </>
              ) : (
                <>
                  <Sparkles className="mr-2 h-5 w-5" />
                  Generate Recipe
                </>
              )}
            </Button>
          </div>

          {/* Recipe Display */}
          {recipe && (
            <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="bg-gradient-to-r from-orange-500 to-amber-500 text-white p-6 rounded-lg shadow-lg">
                <h2 className="text-3xl font-bold mb-2" data-testid="text-recipe-title">{recipe.title}</h2>
                <p className="text-orange-100" data-testid="text-recipe-summary">{recipe.summary}</p>

                <div className="flex flex-wrap gap-4 mt-4">
                  <div className="flex items-center space-x-2">
                    <Clock className="h-5 w-5" />
                    <span>Prep: {recipe.prep_time_minutes} min</span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <Clock className="h-5 w-5" />
                    <span>Cook: {recipe.cook_time_minutes} min</span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <Users className="h-5 w-5" />
                    <span>{recipe.servings} servings</span>
                  </div>
                </div>

                {recipe.tags && recipe.tags.length > 0 && (
                  <div className="flex flex-wrap gap-2 mt-3">
                    {recipe.tags.map((tag, i) => (
                      <Badge key={i} variant="secondary" className="bg-white text-orange-600">
                        {tag}
                      </Badge>
                    ))}
                  </div>
                )}
              </div>

              <div className="grid md:grid-cols-2 gap-6">
                {/* Ingredients */}
                <Card>
                  <CardHeader>
                    <CardTitle className="text-orange-600">Ingredients</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <ul className="space-y-2">
                      {recipe.ingredients.map((ingredient, i) => (
                        <li key={i} className="flex items-start" data-testid={`text-ingredient-${i}`}>
                          <span className="text-orange-500 mr-2">•</span>
                          <span>{ingredient}</span>
                        </li>
                      ))}
                    </ul>
                  </CardContent>
                </Card>

                {/* Instructions */}
                <Card>
                  <CardHeader>
                    <CardTitle className="text-orange-600">Instructions</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <ol className="space-y-3">
                      {recipe.instructions.map((step, i) => (
                        <li key={i} className="flex" data-testid={`text-instruction-${i}`}>
                          <span className="flex-shrink-0 w-8 h-8 bg-orange-100 dark:bg-orange-900 text-orange-600 dark:text-orange-300 rounded-full flex items-center justify-center font-semibold mr-3">
                            {i + 1}
                          </span>
                          <span className="pt-1">{step}</span>
                        </li>
                      ))}
                    </ol>
                  </CardContent>
                </Card>
              </div>

              {/* Pro Tips */}
              {recipe.pro_tips && recipe.pro_tips.length > 0 && (
                <Card className="bg-amber-50 dark:bg-amber-950 border-amber-200">
                  <CardHeader>
                    <CardTitle className="flex items-center text-amber-700 dark:text-amber-300">
                      <Sparkles className="mr-2 h-5 w-5" />
                      Pro Tips
                    </CardTitle>
                  </CardHeader>
                  <CardContent>
                    <ul className="space-y-2">
                      {recipe.pro_tips.map((tip, i) => (
                        <li key={i} className="flex items-start text-amber-800 dark:text-amber-200" data-testid={`text-tip-${i}`}>
                          <span className="mr-2">💡</span>
                          <span>{tip}</span>
                        </li>
                      ))}
                    </ul>
                  </CardContent>
                </Card>
              )}

              {/* Video Link */}
              {recipe.video_url && (
                <div className="flex justify-center">
                  <Button
                    onClick={() => window.open(recipe.video_url, "_blank")}
                    variant="outline"
                    className="border-2 border-orange-500 text-orange-600 hover:bg-orange-50 dark:hover:bg-orange-950"
                    data-testid="button-video-tutorial"
                  >
                    <Youtube className="mr-2 h-5 w-5" />
                    Watch Video Tutorial
                  </Button>
                </div>
              )}
            </div>
          )}

          {!recipe && !isGenerating && (
            <div className="text-center py-12 text-gray-400">
              <UtensilsCrossed className="mx-auto h-16 w-16 mb-4 opacity-50" />
              <p>Enter a dish name above to generate a personalized recipe</p>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

