import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Heart, MessageCircle, Loader2 } from "lucide-react";
import { formatDistanceToNow } from "date-fns";

interface Comment {
  id: number;
  postId: number;
  userId: string;
  content: string;
  parentCommentId: number | null;
  likes: number;
  createdAt: string;
  user: {
    id: string;
    firstName: string | null;
    lastName: string | null;
    profileImageUrl: string | null;
  };
  replies?: Comment[];
  isLiked?: boolean;
}

interface CommentSectionProps {
  postId: number;
  isExpanded: boolean;
}

function CommentItem({ comment, postId, depth = 0 }: { comment: Comment; postId: number; depth?: number }) {
  const [showReplyInput, setShowReplyInput] = useState(false);
  const [replyContent, setReplyContent] = useState("");
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const replyMutation = useMutation({
    mutationFn: async (content: string) => {
      return await apiRequest(`/api/community/posts/${postId}/comments`, "POST", {
        content,
        parentCommentId: comment.id,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/community/posts", postId, "comments"] });
      setReplyContent("");
      setShowReplyInput(false);
      toast({
        title: "Reply posted!",
        description: "Your reply has been added.",
      });
    },
    onError: () => {
      toast({
        title: "Error posting reply",
        description: "Please try again.",
        variant: "destructive",
      });
    },
  });

  const likeMutation = useMutation({
    mutationFn: async () => {
      return await apiRequest(`/api/community/comments/${comment.id}/like`, "POST", {});
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/community/posts", postId, "comments"] });
    },
  });

  const handleReply = () => {
    if (!replyContent.trim()) return;
    replyMutation.mutate(replyContent);
  };

  const handleLike = () => {
    likeMutation.mutate();
  };

  const getInitials = (firstName: string | null, lastName: string | null) => {
    const first = firstName?.[0] || "";
    const last = lastName?.[0] || "";
    return (first + last).toUpperCase() || "U";
  };

  const isNested = depth > 0;

  return (
    <div 
      className={`${isNested ? 'ml-8 pl-4 border-l-2 border-gray-200' : ''}`}
      data-testid={`comment-${comment.id}`}
    >
      <div className="flex space-x-3 mb-3">
        <Avatar className="w-8 h-8 flex-shrink-0">
          <AvatarImage src={comment.user.profileImageUrl || ""} />
          <AvatarFallback className="bg-gradient-to-br from-primary to-primary/80 text-white text-xs">
            {getInitials(comment.user.firstName, comment.user.lastName)}
          </AvatarFallback>
        </Avatar>
        <div className="flex-1">
          <div className="bg-gray-50 rounded-lg px-3 py-2">
            <h5 className="font-semibold text-sm text-gray-800">
              {comment.user.firstName || 'User'} {comment.user.lastName || ''}
            </h5>
            <p className="text-gray-700 text-sm mt-1">{comment.content}</p>
          </div>
          <div className="flex items-center space-x-4 mt-1 text-xs text-gray-500">
            <span>{formatDistanceToNow(new Date(comment.createdAt), { addSuffix: true })}</span>
            <Button
              variant="ghost"
              size="sm"
              onClick={handleLike}
              className="h-auto p-0 hover:bg-transparent hover:text-primary flex items-center space-x-1"
              data-testid={`button-like-comment-${comment.id}`}
            >
              <Heart className={`h-3 w-3 ${comment.isLiked ? 'fill-primary text-primary' : ''}`} />
              <span>{comment.likes > 0 ? comment.likes : 'Like'}</span>
            </Button>
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setShowReplyInput(!showReplyInput)}
              className="h-auto p-0 hover:bg-transparent hover:text-primary flex items-center space-x-1"
              data-testid={`button-reply-${comment.id}`}
            >
              <MessageCircle className="h-3 w-3" />
              <span>Reply</span>
            </Button>
          </div>

          {showReplyInput && (
            <div className="mt-3 space-y-2">
              <Textarea
                placeholder="Write a reply..."
                value={replyContent}
                onChange={(e) => setReplyContent(e.target.value)}
                rows={2}
                className="text-sm"
                data-testid={`input-comment-reply-${comment.id}`}
              />
              <div className="flex space-x-2">
                <Button
                  size="sm"
                  onClick={handleReply}
                  disabled={replyMutation.isPending || !replyContent.trim()}
                  className="bg-primary text-white hover:bg-primary/90"
                >
                  {replyMutation.isPending ? (
                    <>
                      <Loader2 className="mr-1 h-3 w-3 animate-spin" />
                      Posting...
                    </>
                  ) : (
                    'Post Reply'
                  )}
                </Button>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => {
                    setShowReplyInput(false);
                    setReplyContent("");
                  }}
                >
                  Cancel
                </Button>
              </div>
            </div>
          )}
        </div>
      </div>

      {comment.replies && comment.replies.length > 0 && (
        <div className="mt-3 space-y-3">
          {comment.replies.map((reply) => (
            <CommentItem key={reply.id} comment={reply} postId={postId} depth={depth + 1} />
          ))}
        </div>
      )}
    </div>
  );
}

export default function CommentSection({ postId, isExpanded }: CommentSectionProps) {
  const [newComment, setNewComment] = useState("");
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const { data: comments = [], isLoading } = useQuery<Comment[]>({
    queryKey: ["/api/community/posts", postId, "comments"],
    enabled: isExpanded,
    retry: false,
  });

  const createCommentMutation = useMutation({
    mutationFn: async (content: string) => {
      return await apiRequest(`/api/community/posts/${postId}/comments`, "POST", {
        content,
        parentCommentId: null,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/community/posts", postId, "comments"] });
      queryClient.invalidateQueries({ queryKey: ["/api/community/posts"] });
      setNewComment("");
      toast({
        title: "Comment posted!",
        description: "Your comment has been added.",
      });
    },
    onError: () => {
      toast({
        title: "Error posting comment",
        description: "Please try again.",
        variant: "destructive",
      });
    },
  });

  const handleCreateComment = () => {
    if (!newComment.trim()) return;
    createCommentMutation.mutate(newComment);
  };

  if (!isExpanded) return null;

  return (
    <div className="mt-4 pt-4 border-t border-gray-200">
      <div className="space-y-4">
        <div className="space-y-2">
          <Textarea
            placeholder="Add a comment..."
            value={newComment}
            onChange={(e) => setNewComment(e.target.value)}
            rows={3}
            data-testid={`input-add-comment-${postId}`}
          />
          <Button
            onClick={handleCreateComment}
            disabled={createCommentMutation.isPending || !newComment.trim()}
            className="bg-primary text-white hover:bg-primary/90"
          >
            {createCommentMutation.isPending ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Posting...
              </>
            ) : (
              'Post Comment'
            )}
          </Button>
        </div>

        {isLoading ? (
          <div className="text-center py-8">
            <Loader2 className="w-6 h-6 animate-spin mx-auto text-primary" />
            <p className="text-gray-600 text-sm mt-2">Loading comments...</p>
          </div>
        ) : comments.length === 0 ? (
          <div className="text-center py-8">
            <MessageCircle className="mx-auto h-8 w-8 text-gray-400 mb-2" />
            <p className="text-sm text-gray-600">No comments yet. Be the first to comment!</p>
          </div>
        ) : (
          <div className="space-y-4">
            {comments.map((comment) => (
              <CommentItem key={comment.id} comment={comment} postId={postId} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

client/src/pages/subscription-success.ts.content:
import { useEffect, useState } from "react";
import { useLocation } from "wouter";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { CheckCircle, Loader2, XCircle, Download, Calendar, DollarSign } from "lucide-react";
import { useQuery } from "@tanstack/react-query";
import Navigation from "@/components/navigation";

interface Payment {
  id: number;
  userId: string;
  amount: string;
  planName: string;
  expiresAt: string;
  invoiceUrl: string | null;
  receiptUrl: string | null;
  billingAddress: any;
  createdAt: string;
}

export default function SubscriptionSuccess() {
  const [, navigate] = useLocation();
  const [verifying, setVerifying] = useState(true);
  const [payment, setPayment] = useState<Payment | null>(null);

  // Get session_id from URL (Stripe Checkout redirect)
  const params = new URLSearchParams(window.location.search);
  const sessionId = params.get("session_id");

  useEffect(() => {
    const verifyPayment = async () => {
      if (!sessionId) {
        setVerifying(false);
        return;
      }

      // Wait for webhook to process
      await new Promise(resolve => setTimeout(resolve, 3000));

      try {
        // Fetch the checkout session details
        const sessionResponse = await fetch(`/api/checkout-session/${sessionId}`, {
          credentials: "include"
        });

        if (sessionResponse.ok) {
          const sessionData = await sessionResponse.json();

          // Check if payment was successful using native Stripe fields
          // Stripe returns status='complete' with payment_status='paid' for successful payments
          if (sessionData.payment_status === 'paid' && sessionData.status === 'complete' && sessionData.paymentIntentId) {
            // Fetch the payment record from our database
            const paymentResponse = await fetch(`/api/payment/${sessionData.paymentIntentId}`, {
              credentials: "include"
            });

            if (paymentResponse.ok) {
              const paymentData = await paymentResponse.json();

              // Verify this is a recent payment
              const paymentAge = Date.now() - new Date(paymentData.createdAt).getTime();
              const fiveMinutes = 5 * 60 * 1000;

              if (paymentAge < fiveMinutes && paymentData.status === 'succeeded') {
                setPayment(paymentData);
              } else {
                console.error("Payment verification failed: payment is too old or not succeeded");
              }
            } else {
              console.error("Payment record not found in database");
            }
          } else {
            console.error("Checkout session payment not completed");
          }
        } else {
          console.error("Checkout session not found");
        }
      } catch (error) {
        console.error("Failed to fetch payment:", error);
      }

      setVerifying(false);
    };

    verifyPayment();
  }, [sessionId]);

  if (verifying) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-purple-50">
        <Navigation />
        <div className="container mx-auto px-4 py-20">
          <Card className="max-w-md mx-auto text-center">
            <CardHeader>
              <Loader2 className="w-16 h-16 text-primary mx-auto animate-spin mb-4" />
              <CardTitle>Verifying Your Purchase</CardTitle>
              <CardDescription>
                Please wait while we confirm your payment...
              </CardDescription>
            </CardHeader>
          </Card>
        </div>
      </div>
    );
  }

  if (payment) {
    const expiryDate = new Date(payment.expiresAt);
    const daysRemaining = Math.ceil((expiryDate.getTime() - Date.now()) / (1000 * 60 * 60 * 24));

    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-purple-50">
        <Navigation />
        <div className="container mx-auto px-4 py-20">
          <Card className="max-w-2xl mx-auto">
            <CardHeader className="text-center">
              <CheckCircle className="w-16 h-16 text-green-500 mx-auto mb-4" />
              <CardTitle className="text-3xl">Purchase Complete!</CardTitle>
              <CardDescription className="text-lg">
                You now have full access to MikeAI Plus
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              {/* Purchase Details */}
              <div className="bg-gradient-to-br from-primary/10 to-blue-50 p-6 rounded-lg space-y-4">
                <h3 className="font-bold text-gray-900 text-lg mb-4">Purchase Details</h3>

                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 text-gray-700">
                    <DollarSign className="w-5 h-5" />
                    <span className="font-medium">Amount Paid</span>
                  </div>
                  <span className="font-bold text-xl text-primary">${payment.amount}</span>
                </div>

                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 text-gray-700">
                    <Calendar className="w-5 h-5" />
                    <span className="font-medium">Access Expires</span>
                  </div>
                  <span className="font-semibold">{expiryDate.toLocaleDateString()}</span>
                </div>

                <div className="bg-white/80 p-3 rounded-lg">
                  <p className="text-sm text-gray-600 text-center">
                    <span className="font-bold text-primary">{daysRemaining} days</span> of full access remaining
                  </p>
                </div>
              </div>

              {/* Features */}
              <div className="bg-green-50 p-6 rounded-lg">
                <h3 className="font-semibold text-green-900 mb-3">You now have access to:</h3>
                <ul className="text-sm text-green-800 space-y-2">
                  <li>✓ Unlimited AI meal plans</li>
                  <li>✓ Custom workout programs</li>
                  <li>✓ 24/7 Fitness GPT AI Coach</li>
                  <li>✓ AI supplement recommendations</li>
                  <li>✓ All premium features for 30 days!</li>
                </ul>
              </div>

              {/* Invoice Download */}
              {payment.invoiceUrl && (
                <div className="border-t pt-4">
                  <a
                    href={payment.invoiceUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center justify-center gap-2 text-primary hover:text-primary/80 font-medium"
                  >
                    <Download className="w-5 h-5" />
                    Download Invoice (PDF)
                  </a>
                </div>
              )}

              <Button 
                onClick={() => navigate("/")}
                className="w-full"
                size="lg"
                data-testid="button-go-dashboard"
              >
                Go to Dashboard
              </Button>
            </CardContent>
          </Card>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-purple-50">
      <Navigation />
      <div className="container mx-auto px-4 py-20">
        <Card className="max-w-md mx-auto text-center">
          <CardHeader>
            <XCircle className="w-16 h-16 text-red-500 mx-auto mb-4" />
            <CardTitle className="text-2xl">Purchase Verification Failed</CardTitle>
            <CardDescription>
              We couldn't verify your purchase. Please contact support if you were charged.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <Button 
              onClick={() => navigate("/subscription")}
              variant="outline"
              className="w-full"
            >
              Try Again
            </Button>
            <Button 
              onClick={() => navigate("/")}
              className="w-full"
            >
              Go to Dashboard
            </Button>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

client/src/pages/purchase-history.tsx.content:
import { useQuery } from "@tanstack/react-query";
import Navigation from "@/components/navigation";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { 
  Calendar, 
  DollarSign, 
  Download, 
  MapPin, 
  CreditCard,
  Clock,
  CheckCircle,
  XCircle
} from "lucide-react";

interface Payment {
  id: number;
  userId: string;
  amount: string;
  planName: string;
  expiresAt: string;
  status: string;
  invoiceUrl: string | null;
  receiptUrl: string | null;
  billingAddress: {
    name?: string;
    line1?: string;
    line2?: string;
    city?: string;
    state?: string;
    postal_code?: string;
    country?: string;
  };
  createdAt: string;
}

export default function PurchaseHistory() {
  const { data: payments, isLoading } = useQuery<Payment[]>({
    queryKey: ["/api/user/payments"],
  });

  const { data: activePayment } = useQuery<Payment>({
    queryKey: ["/api/user/active-payment"],
    retry: false,
  });

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString("en-US", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  };

  const isExpired = (expiresAt: string) => {
    return new Date(expiresAt) < new Date();
  };

  const getDaysRemaining = (expiresAt: string) => {
    const days = Math.ceil((new Date(expiresAt).getTime() - Date.now()) / (1000 * 60 * 60 * 24));
    return days > 0 ? days : 0;
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-purple-50">
      <Navigation />

      <div className="container mx-auto px-4 py-8 max-w-6xl">
        <div className="mb-8">
          <h1 className="text-4xl font-bold text-gray-900 mb-2">Purchase History</h1>
          <p className="text-gray-600">View all your past purchases and download invoices</p>
        </div>

        {/* Active Access Status Card */}
        {activePayment && (
          <Card className="mb-8 border-2 border-primary/20 bg-gradient-to-br from-primary/5 to-blue-50">
            <CardHeader>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-green-500 rounded-full">
                    <CheckCircle className="w-6 h-6 text-white" />
                  </div>
                  <div>
                    <CardTitle className="text-2xl">Active Access</CardTitle>
                    <CardDescription className="text-base">You have full access to MikeAI Plus</CardDescription>
                  </div>
                </div>
                <Badge className="px-4 py-2 text-sm bg-green-500 hover:bg-green-600">
                  Active
                </Badge>
              </div>
            </CardHeader>
            <CardContent>
              <div className="grid md:grid-cols-2 gap-4">
                <div className="flex items-center gap-3 p-4 bg-white/80 rounded-lg">
                  <Clock className="w-5 h-5 text-primary" />
                  <div>
                    <p className="text-sm text-gray-600">Days Remaining</p>
                    <p className="font-bold text-lg text-primary">
                      {getDaysRemaining(activePayment.expiresAt)} days
                    </p>
                  </div>
                </div>
                <div className="flex items-center gap-3 p-4 bg-white/80 rounded-lg">
                  <Calendar className="w-5 h-5 text-primary" />
                  <div>
                    <p className="text-sm text-gray-600">Expires On</p>
                    <p className="font-semibold">{formatDate(activePayment.expiresAt)}</p>
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        )}

        {/* Purchase History */}
        <Card>
          <CardHeader>
            <CardTitle>All Purchases</CardTitle>
            <CardDescription>Complete history of your transactions</CardDescription>
          </CardHeader>
          <CardContent>
            {isLoading ? (
              <div className="text-center py-8">
                <p className="text-gray-500">Loading purchases...</p>
              </div>
            ) : !payments || payments.length === 0 ? (
              <div className="text-center py-12">
                <CreditCard className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                <h3 className="text-xl font-semibold text-gray-700 mb-2">No purchases yet</h3>
                <p className="text-gray-500 mb-6">Get started with MikeAI Plus for just $4.99</p>
                <Button data-testid="button-get-access">
                  <a href="/subscription">Get 30 Days Access</a>
                </Button>
              </div>
            ) : (
              <div className="space-y-4">
                {payments.map((payment, index) => {
                  const expired = isExpired(payment.expiresAt);

                  return (
                    <div key={payment.id}>
                      <div className="p-6 rounded-lg border hover:shadow-md transition-shadow">
                        {/* Header Row */}
                        <div className="flex items-start justify-between mb-4">
                          <div className="flex items-center gap-3">
                            <div className={`p-2 rounded-full ${expired ? 'bg-gray-200' : 'bg-green-100'}`}>
                              {expired ? (
                                <XCircle className="w-5 h-5 text-gray-600" />
                              ) : (
                                <CheckCircle className="w-5 h-5 text-green-600" />
                              )}
                            </div>
                            <div>
                              <h3 className="font-bold text-lg">{payment.planName}</h3>
                              <p className="text-sm text-gray-500">
                                Purchased on {formatDate(payment.createdAt)}
                              </p>
                            </div>
                          </div>
                          <Badge variant={expired ? "outline" : "default"} className="px-3 py-1">
                            {expired ? "Expired" : "Active"}
                          </Badge>
                        </div>

                        {/* Details Grid */}
                        <div className="grid md:grid-cols-3 gap-4 mb-4">
                          <div className="flex items-center gap-2">
                            <DollarSign className="w-4 h-4 text-gray-400" />
                            <div>
                              <p className="text-xs text-gray-500">Amount Paid</p>
                              <p className="font-semibold text-primary">${payment.amount}</p>
                            </div>
                          </div>

                          <div className="flex items-center gap-2">
                            <Calendar className="w-4 h-4 text-gray-400" />
                            <div>
                              <p className="text-xs text-gray-500">Expiration Date</p>
                              <p className="font-semibold">{formatDate(payment.expiresAt)}</p>
                            </div>
                          </div>

                          <div className="flex items-center gap-2">
                            <Clock className="w-4 h-4 text-gray-400" />
                            <div>
                              <p className="text-xs text-gray-500">Access Period</p>
                              <p className="font-semibold">30 Days</p>
                            </div>
                          </div>
                        </div>

                        {/* Billing Address */}
                        {payment.billingAddress && (
                          <div className="bg-gray-50 p-4 rounded-lg mb-4">
                            <div className="flex items-start gap-2">
                              <MapPin className="w-4 h-4 text-gray-400 mt-1" />
                              <div>
                                <p className="text-xs text-gray-500 font-medium mb-1">Billing Address</p>
                                <p className="text-sm">{payment.billingAddress.name}</p>
                                <p className="text-sm">{payment.billingAddress.line1}</p>
                                {payment.billingAddress.line2 && (
                                  <p className="text-sm">{payment.billingAddress.line2}</p>
                                )}
                                <p className="text-sm">
                                  {payment.billingAddress.city}, {payment.billingAddress.state} {payment.billingAddress.postal_code}
                                </p>
                                <p className="text-sm">{payment.billingAddress.country}</p>
                              </div>
                            </div>
                          </div>
                        )}

                        {/* Action Buttons */}
                        <div className="flex gap-3">
                          {payment.invoiceUrl && (
                            <Button 
                              variant="outline" 
                              size="sm" 
                              asChild
                              data-testid={`button-download-invoice-${payment.id}`}
                            >
                              <a 
                                href={payment.invoiceUrl} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                className="flex items-center gap-2"
                              >
                                <Download className="w-4 h-4" />
                                Download Invoice
                              </a>
                            </Button>
                          )}
                          {payment.receiptUrl && (
                            <Button 
                              variant="outline" 
                              size="sm" 
                              asChild
                              data-testid={`button-download-receipt-${payment.id}`}
                            >
                              <a 
                                href={payment.receiptUrl} 
                                target="_blank" 
                                rel="noopener noreferrer"
                                className="flex items-center gap-2"
                              >
                                <Download className="w-4 h-4" />
                                Download Receipt
                              </a>
                            </Button>
                          )}
                        </div>
                      </div>

                      {index < payments.length - 1 && <Separator className="my-4" />}
                    </div>
                  );
                })}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Renewal Reminder */}
        {!activePayment && payments && payments.length > 0 && (
          <Card className="mt-8 border-2 border-orange-200 bg-orange-50/50">
            <CardContent className="p-6">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-orange-100 rounded-full">
                  <Clock className="w-6 h-6 text-orange-600" />
                </div>
                <div className="flex-1">
                  <h3 className="font-bold text-lg text-gray-900 mb-1">Your access has expired</h3>
                  <p className="text-gray-600">Renew now to continue using all premium features</p>
                </div>
                <Button className="bg-orange-500 hover:bg-orange-600" data-testid="button-renew-access">
                  <a href="/subscription">Renew Access - $4.99</a>
                </Button>
              </div>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

client/src/components/subscription-statu.content:
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Crown, Calendar, AlertCircle, CheckCircle, Sparkles } from "lucide-react";
import { useLocation } from "wouter";

interface SubscriptionInfo {
  subscriptionStatus: string;
  subscriptionTier: string;
  expiresAt: string | null;
  daysRemaining: number;
  isExpired: boolean;
  activePayment: any;
}

export default function SubscriptionStatusCard() {
  const [, navigate] = useLocation();

  const { data: subInfo, isLoading } = useQuery<SubscriptionInfo>({
    queryKey: ["/api/user/subscription-info"],
  });

  if (isLoading) {
    return (
      <Card className="bg-gradient-to-br from-primary/5 via-blue-50 to-purple-50 border-primary/20">
        <CardHeader>
          <div className="animate-pulse space-y-2">
            <div className="h-6 bg-gray-200 rounded w-1/3"></div>
            <div className="h-4 bg-gray-200 rounded w-1/2"></div>
          </div>
        </CardHeader>
      </Card>
    );
  }

  if (!subInfo) return null;

  const { subscriptionStatus, subscriptionTier, expiresAt, daysRemaining, isExpired } = subInfo;

  // Determine status color and icon
  const getStatusConfig = () => {
    if (subscriptionTier === 'plus' && !isExpired) {
      return {
        color: 'bg-gradient-to-r from-primary to-blue-600',
        textColor: 'text-white',
        icon: <Crown className="w-5 h-5" />,
        badge: 'PLUS',
        badgeColor: 'bg-amber-500 text-white',
        showRenew: daysRemaining <= 7
      };
    } else if (isExpired) {
      return {
        color: 'bg-gradient-to-r from-gray-400 to-gray-500',
        textColor: 'text-white',
        icon: <AlertCircle className="w-5 h-5" />,
        badge: 'EXPIRED',
        badgeColor: 'bg-red-500 text-white',
        showRenew: true
      };
    } else {
      return {
        color: 'bg-gradient-to-r from-gray-100 to-gray-200',
        textColor: 'text-gray-900',
        icon: <Sparkles className="w-5 h-5" />,
        badge: 'FREE TRIAL',
        badgeColor: 'bg-blue-500 text-white',
        showRenew: false
      };
    }
  };

  const config = getStatusConfig();

  return (
    <Card className={`${config.color} shadow-lg border-0`}>
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className={`p-2 rounded-lg bg-white/20 ${config.textColor}`}>
              {config.icon}
            </div>
            <div>
              <CardTitle className={`text-lg ${config.textColor}`}>
                Your Plan
              </CardTitle>
              <CardDescription className={`${config.textColor} opacity-90`}>
                Current subscription status
              </CardDescription>
            </div>
          </div>
          <Badge className={config.badgeColor}>
            {config.badge}
          </Badge>
        </div>
      </CardHeader>
      <CardContent className="space-y-3">
        {/* Expiry Information */}
        {expiresAt && !isExpired && (
          <div className={`flex items-center justify-between p-3 rounded-lg bg-white/10 ${config.textColor}`}>
            <div className="flex items-center gap-2">
              <Calendar className="w-4 h-4" />
              <span className="text-sm font-medium">Expires</span>
            </div>
            <div className="text-right">
              <p className="text-sm font-bold">
                {new Date(expiresAt).toLocaleDateString()}
              </p>
              <p className="text-xs opacity-80">
                {daysRemaining} day{daysRemaining !== 1 ? 's' : ''} remaining
              </p>
            </div>
          </div>
        )}

        {/* Expired Message */}
        {isExpired && (
          <div className={`flex items-center gap-2 p-3 rounded-lg bg-white/10 ${config.textColor}`}>
            <AlertCircle className="w-4 h-4" />
            <span className="text-sm font-medium">Your subscription has expired</span>
          </div>
        )}

        {/* Free Trial Message */}
        {subscriptionTier === 'free' && !isExpired && (
          <div className={`flex items-center gap-2 p-3 rounded-lg bg-white/10 ${config.textColor}`}>
            <CheckCircle className="w-4 h-4" />
            <span className="text-sm font-medium">Limited access to basic features</span>
          </div>
        )}

        {/* Renew/Upgrade Button */}
        {(config.showRenew || subscriptionTier === 'free') && (
          <Button
            onClick={() => navigate('/subscription')}
            className="w-full bg-white hover:bg-gray-100 text-gray-900 font-semibold shadow-md"
            data-testid="button-upgrade-renew"
          >
            {isExpired ? 'Renew Now' : subscriptionTier === 'free' ? 'Upgrade to Plus' : 'Renew Early'}
          </Button>
        )}

        {/* Active Subscription Message */}
        {subscriptionTier === 'plus' && !isExpired && daysRemaining > 7 && (
          <div className={`text-center text-sm ${config.textColor} opacity-90`}>
            <CheckCircle className="w-4 h-4 inline mr-1" />
            All premium features unlocked
          </div>
        )}
      </CardContent>
    </Card>
  );
}

client/src/components/DayMappingEditor.t.content:
import { useState, useEffect } from "react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Calendar, RotateCcw } from "lucide-react";

const WEEKDAYS = [
  "monday",
  "tuesday",
  "wednesday",
  "thursday",
  "friday",
  "saturday",
  "sunday",
] as const;

const WEEKDAY_LABELS: Record<string, string> = {
  monday: "Monday",
  tuesday: "Tuesday",
  wednesday: "Wednesday",
  thursday: "Thursday",
  friday: "Friday",
  saturday: "Saturday",
  sunday: "Sunday",
};

interface DayMappingEditorProps {
  planDays: number; // Number of days in the plan (e.g., 3, 4, 5, 6)
  defaultStartDay?: string; // Default start day (e.g., "monday")
  value?: Record<string, string>; // weekday → plan day index or "rest"
  onChange: (mapping: Record<string, string>) => void;
  planType?: "meal" | "workout";
}

export function DayMappingEditor({
  planDays,
  defaultStartDay = "monday",
  value,
  onChange,
  planType = "workout"
}: DayMappingEditorProps) {
  const [mapping, setMapping] = useState<Record<string, string>>({});

  // Initialize mapping with default values
  useEffect(() => {
    if (value && Object.keys(value).length > 0) {
      // Check if this is old format (planDayIndex → weekday) or new format (weekday → planDayIndex)
      const firstKey = Object.keys(value)[0];
      const firstValue = value[firstKey];
      const weekdayNames = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"];

      // Old format: keys are numbers (plan day indices), values are weekdays
      if (!isNaN(parseInt(firstKey)) && typeof firstValue === 'string' && weekdayNames.includes(firstValue.toLowerCase())) {
        // Convert old format to new format
        const newMapping: Record<string, string> = {};
        for (const [planDayIndex, weekday] of Object.entries(value)) {
          newMapping[weekday.toLowerCase()] = planDayIndex;
        }
        setMapping(newMapping);
        onChange(newMapping); // Update parent with new format
      } else {
        // Already new format
        setMapping(value);
      }
    } else {
      // Create default mapping: map weekdays sequentially to plan days, rest of week = rest
      const startIndex = WEEKDAYS.indexOf(defaultStartDay as any);
      const defaultMapping: Record<string, string> = {};

      for (let i = 0; i < 7; i++) {
        const weekdayIndex = (startIndex + i) % 7;
        const weekday = WEEKDAYS[weekdayIndex];

        if (i < planDays) {
          // Map to plan day index
          defaultMapping[weekday] = i.toString();
        } else {
          // Rest day
          defaultMapping[weekday] = "rest";
        }
      }

      setMapping(defaultMapping);
      onChange(defaultMapping);
    }
  }, [planDays, defaultStartDay, value, onChange]);

  const handleDayChange = (weekday: string, planDayValue: string) => {
    const oldValue = mapping[weekday];

    // If changing to "rest" from a plan day, cascade the plan day forward to the next available weekday
    if (planDayValue === "rest" && oldValue !== "rest" && oldValue !== undefined) {
      const removedPlanDay = oldValue; // The plan day we're removing from this weekday
      const newMapping = { ...mapping };

      // Set this weekday to rest
      newMapping[weekday] = "rest";

      // Cascade the plan day forward through all subsequent weekdays
      const currentWeekdayIndex = WEEKDAYS.indexOf(weekday as any);
      let dayToCascade = removedPlanDay;
      let foundRestDay = false;

      // Start from the next weekday and cascade forward
      for (let i = 1; i <= 7; i++) {
        const nextWeekdayIndex = (currentWeekdayIndex + i) % 7;
        const nextWeekday = WEEKDAYS[nextWeekdayIndex];
        const nextAssignment = newMapping[nextWeekday];

        if (nextAssignment === "rest") {
          // Found a rest day - place the cascading plan day here and stop
          newMapping[nextWeekday] = dayToCascade;
          foundRestDay = true;
          break;
        } else if (i === 7) {
          // Completed full circle, no rest day found
          // Place the final displaced day back on the current weekday (rotation effect)
          newMapping[weekday] = dayToCascade;
          break;
        } else {
          // This day already has a plan day - swap and continue cascading
          const temp = nextAssignment;
          newMapping[nextWeekday] = dayToCascade;
          dayToCascade = temp;
        }
      }

      setMapping(newMapping);
      onChange(newMapping);
    } 
    // If changing from "rest" to a plan day, check for duplicates and handle intelligently
    else if (oldValue === "rest" && planDayValue !== "rest") {
      const newMapping = { ...mapping, [weekday]: planDayValue };

      // Check if this plan day is already assigned elsewhere
      const duplicateWeekday = WEEKDAYS.find(
        wd => wd !== weekday && newMapping[wd] === planDayValue
      );

      // If duplicate exists, swap: give this weekday the selected plan day, and make the other one rest
      if (duplicateWeekday) {
        newMapping[duplicateWeekday] = "rest";
      }

      setMapping(newMapping);
      onChange(newMapping);
    }
    // Simple assignment change (e.g., changing from Day 1 to Day 2)
    else {
      const newMapping = { ...mapping, [weekday]: planDayValue };
      setMapping(newMapping);
      onChange(newMapping);
    }
  };

  const resetToDefault = () => {
    const startIndex = WEEKDAYS.indexOf(defaultStartDay as any);
    const defaultMapping: Record<string, string> = {};

    for (let i = 0; i < 7; i++) {
      const weekdayIndex = (startIndex + i) % 7;
      const weekday = WEEKDAYS[weekdayIndex];

      if (i < planDays) {
        defaultMapping[weekday] = i.toString();
      } else {
        defaultMapping[weekday] = "rest";
      }
    }

    setMapping(defaultMapping);
    onChange(defaultMapping);
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Calendar className="h-5 w-5 text-primary" />
          <h3 className="text-lg font-semibold">Map Days to Week</h3>
        </div>
        <Button
          variant="outline"
          size="sm"
          onClick={resetToDefault}
          data-testid="button-reset-day-mapping"
        >
          <RotateCcw className="h-4 w-4 mr-2" />
          Reset to Default
        </Button>
      </div>

      <p className="text-sm text-muted-foreground">
        Assign each weekday to a specific day from your {planDays}-day {planType} plan, or mark it as a rest day.
      </p>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {WEEKDAYS.map((weekday) => (
          <Card key={weekday} className="p-4">
            <div className="space-y-3">
              <Label className="text-sm font-medium">
                {WEEKDAY_LABELS[weekday]}
              </Label>
              <Select
                value={mapping[weekday] || "rest"}
                onValueChange={(value) => handleDayChange(weekday, value)}
              >
                <SelectTrigger data-testid={`select-${weekday}-mapping`}>
                  <SelectValue placeholder="Select assignment" />
                </SelectTrigger>
                <SelectContent>
                  {Array.from({ length: planDays }).map((_, index) => (
                    <SelectItem key={index} value={index.toString()}>
                      {planType === "workout" ? `Day ${index + 1}` : `Meal Day ${index + 1}`}
                    </SelectItem>
                  ))}
                  <SelectItem value="rest">Rest Day</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </Card>
        ))}
      </div>

      <div className="mt-6 p-4 bg-muted rounded-lg">
        <h4 className="font-semibold mb-3">Weekly Schedule Preview</h4>
        <div className="grid grid-cols-7 gap-2">
          {WEEKDAYS.map((weekday) => {
            const assignment = mapping[weekday];
            const isRest = !assignment || assignment === "rest";

            return (
              <div
                key={weekday}
                className={`p-3 rounded text-center text-sm ${
                  !isRest
                    ? "bg-primary text-primary-foreground font-medium"
                    : "bg-background text-muted-foreground"
                }`}
                data-testid={`preview-${weekday}`}
              >
                <div className="font-semibold text-xs uppercase">
                  {weekday.slice(0, 3)}
                </div>
                <div className="mt-1 text-xs">
                  {isRest ? "Rest" : `Day ${parseInt(assignment) + 1}`}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

client/src/components/FullWeekWorkoutPla.content:
import React from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Dumbbell, Timer, Repeat } from "lucide-react";

interface Exercise {
  name: string;
  sets: number | string;
  reps: number | string;
  rest?: number | string;
  restSec?: number | string;
}

interface WorkoutDay {
  name?: string;
  day?: string;
  exercises?: Exercise[];
  items?: Exercise[];
}

interface FullWeekWorkoutPlanViewerProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  planName: string;
  planData: {
    days?: WorkoutDay[];
  } | WorkoutDay[];
  dayMapping?: Record<string, string> | null;
}

const WEEKDAY_ORDER = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"];
const WEEKDAY_LABELS: Record<string, string> = {
  monday: "Monday",
  tuesday: "Tuesday",
  wednesday: "Wednesday",
  thursday: "Thursday",
  friday: "Friday",
  saturday: "Saturday",
  sunday: "Sunday",
};

export function FullWeekWorkoutPlanViewer({ 
  open, 
  onOpenChange, 
  planName,
  planData,
  dayMapping 
}: FullWeekWorkoutPlanViewerProps) {

  // Normalize planData to array of days
  const days: WorkoutDay[] = Array.isArray(planData) 
    ? planData 
    : (planData?.days || []);

  // Migrate legacy dayMapping format to new format
  const normalizedDayMapping = React.useMemo(() => {
    if (!dayMapping || Object.keys(dayMapping).length === 0) {
      return null;
    }

    // Check if this is old format (planDayIndex → weekday) or new format (weekday → planDayIndex)
    const firstKey = Object.keys(dayMapping)[0];
    const firstValue = dayMapping[firstKey];

    // Old format: keys are numbers (plan day indices), values are weekdays
    if (!isNaN(parseInt(firstKey)) && typeof firstValue === 'string' && WEEKDAY_ORDER.includes(firstValue.toLowerCase())) {
      // Convert old format to new format
      const newMapping: Record<string, string> = {};
      for (const [planDayIndex, weekday] of Object.entries(dayMapping)) {
        newMapping[weekday.toLowerCase()] = planDayIndex;
      }
      return newMapping;
    }

    // New format: keys are weekdays, values are plan day indices or "rest"
    return dayMapping;
  }, [dayMapping]);

  // Create week structure based on dayMapping
  const weekStructure = WEEKDAY_ORDER.map((weekday, weekdayIndex) => {
    // If normalizedDayMapping exists and is not empty, use it
    if (normalizedDayMapping && Object.keys(normalizedDayMapping).length > 0) {
      const mappedValue = normalizedDayMapping[weekday];

      // Check if this weekday is explicitly marked as rest
      if (!mappedValue || mappedValue === "rest") {
        return {
          weekday,
          label: WEEKDAY_LABELS[weekday],
          dayName: "Rest Day",
          exercises: [],
          isRestDay: true
        };
      }

      // Map to specific plan day
      const planDayIndex = parseInt(mappedValue);
      if (!isNaN(planDayIndex) && planDayIndex >= 0 && planDayIndex < days.length) {
        const planDay = days[planDayIndex];
        const exercises = planDay?.exercises || planDay?.items || [];
        return {
          weekday,
          label: WEEKDAY_LABELS[weekday],
          dayName: planDay?.name || planDay?.day || WEEKDAY_LABELS[weekday],
          exercises,
          isRestDay: exercises.length === 0
        };
      }

      // Invalid mapping - treat as rest day
      return {
        weekday,
        label: WEEKDAY_LABELS[weekday],
        dayName: "Rest Day",
        exercises: [],
        isRestDay: true
      };
    }

    // FALLBACK: No dayMapping - cycle through plan days using modulo
    if (days.length > 0) {
      const planDayIndex = weekdayIndex % days.length;
      const planDay = days[planDayIndex];
      const exercises = planDay?.exercises || planDay?.items || [];
      return {
        weekday,
        label: WEEKDAY_LABELS[weekday],
        dayName: planDay?.name || planDay?.day || WEEKDAY_LABELS[weekday],
        exercises,
        isRestDay: exercises.length === 0
      };
    }

    // No plan days at all - rest day
    return {
      weekday,
      label: WEEKDAY_LABELS[weekday],
      dayName: "Rest Day",
      exercises: [],
      isRestDay: true
    };
  });

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-6xl max-h-[90vh]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Dumbbell className="h-6 w-6 text-purple-600" />
            Full Week Workout Plan: {planName}
          </DialogTitle>
        </DialogHeader>

        <ScrollArea className="h-[calc(90vh-120px)] pr-4">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {weekStructure.map((day) => {
              return (
                <Card key={day.weekday} className="p-4 space-y-3" data-testid={`day-card-${day.weekday}`}>
                  <div className="flex items-center justify-between">
                    <div>
                      <h3 className="font-bold text-lg">{day.label}</h3>
                      {!day.isRestDay && day.dayName !== day.label && (
                        <p className="text-sm text-gray-600">{day.dayName}</p>
                      )}
                    </div>
                    {day.isRestDay && (
                      <Badge variant="outline" className="text-xs">
                        Rest Day
                      </Badge>
                    )}
                  </div>

                  {day.isRestDay ? (
                    <div className="text-center py-8 text-gray-400">
                      <Dumbbell className="h-12 w-12 mx-auto mb-2 opacity-30" />
                      <p className="text-sm">Recovery Day</p>
                    </div>
                  ) : (
                    <div className="space-y-2">
                      {day.exercises.map((exercise, index) => (
                        <div 
                          key={index} 
                          className="p-3 rounded-lg bg-purple-50 border border-purple-200"
                          data-testid={`exercise-${day.weekday}-${index}`}
                        >
                          <p className="font-semibold text-sm text-purple-900 mb-2">{exercise.name}</p>
                          <div className="flex items-center gap-3 text-xs text-gray-600">
                            <div className="flex items-center gap-1">
                              <Repeat className="h-3 w-3" />
                              <span>{exercise.sets} sets</span>
                            </div>
                            <div className="flex items-center gap-1">
                              <span>×</span>
                              <span>{exercise.reps} reps</span>
                            </div>
                            {(exercise.rest || exercise.restSec) && (
                              <div className="flex items-center gap-1">
                                <Timer className="h-3 w-3" />
                                <span>{exercise.rest || exercise.restSec}s</span>
                              </div>
                            )}
                          </div>
                        </div>
                      ))}

                      <div className="p-2 bg-gray-100 rounded-lg border border-gray-200 text-center">
                        <p className="text-xs text-gray-600">
                          <span className="font-bold">{day.exercises.length}</span> exercise{day.exercises.length !== 1 ? 's' : ''}
                        </p>
                      </div>
                    </div>
                  )}
                </Card>
              );
            })}
          </div>
        </ScrollArea>
      </DialogContent>
    </Dialog>
  );
}

